#include <iostream>
int main() {
    int  a = 42;
    int* p = &a;            // p 保存变量 a 的地址

    std::cout << "a  = " << a  << "\n";
    std::cout << "&a = " << &a << "\n";   // 0x7fff...
    std::cout << "p  = " << p  << "\n";   // 与 &a 相同
    std::cout << "*p = " << *p << "\n";   // 解引用 = 42

    *p = 100;               // 通过指针间接修改 a
    std::cout << a << "\n";              // 100
}

#include <iostream>
int main() {
    int x = 10;
    int* p = &x;          // &x 取址，赋给指针

    std::cout << *p << "\n";     // 读取: 10
    *p = 20;              // 写入 p 指向的内存
    std::cout << x << "\n";      // 20

    // 逆运算验证
    std::cout << (*(&x) == x);    // 1
    std::cout << (&(*p) == p);    // 1
}

void use(int* p) {
    if (p == nullptr) {           // 入口判空
        std::cerr << "空指针!\n";
        return;
    }
    *p += 1;
}

int main() {
    int* p = nullptr;
    use(p);                        // 安全：判空拦截

    p = new int(5);
    use(p);                        // *p == 6

    delete p;
    p = nullptr;                   // 释放后置空，防 double-free
    use(p);                        // 再次安全
}

