#include <iostream>
int main() {
    int arr[] = {5, 9, 2, 7, 1};
    int* begin = arr;                 // 首元素
    int* end   = arr + 5;             // 尾后指针（合法边界）

    // 用指针遍历
    for (int* p = begin; p != end; ++p)
        std::cout << *p << ' ';       // 5 9 2 7 1

    std::ptrdiff_t n = end - begin;   // 5，元素个数
    std::cout << "\ncount = " << n << "\n";

    int* mid = begin + 2;             // &arr[2]
    std::cout << *mid << "\n";       // 2
    std::cout << (begin < end) << "\n";     // 1
}

