// *pp 就是调用者的指针变量
void my_alloc(int** pp) {
    *pp = new int(7);            // 改掉外面指针的指向
}

void my_alloc_ref(int*& p) {     // 等价写法：指针的引用
    p = new int(8);
}

int main() {
    int* p = nullptr;

    my_alloc(&p);                // p 现在是 new int(7)
    std::cout << *p << "\n";     // 7
    delete p; p = nullptr;

    my_alloc_ref(p);             // p 现在是 new int(8)
    std::cout << *p << "\n";     // 8
    delete p;
}

