void swap(int& a, int& b) {      // 引用必须传真实变量
    int t = a; a = b; b = t;
}
void swap_ptr(int* a, int* b) {   // 指针需判空
    if (!a || !b) return;
    int t = *a; *a = *b; *b = t;
}

int main() {
    int x = 1, y = 2;
    swap(x, y);                   // 引用：必传、必用
    std::cout << x << y << "\n";  // 21

    swap_ptr(&x, &y);             // 指针：可判空、可传空
    std::cout << x << y << "\n";  // 12
    swap_ptr(&x, nullptr);        // 空安全返回

    const int& rx = x;            // 只读大对象用 const&
    // rx = 5;                   // 错误：const 引用只读
}

