int main() {
    // 1) 悬空指针
    int* p = new int(5);
    delete p;
    *p = 9;                    // BUG: 访问已释放内存 (UB)

    // 2) 内存泄漏
    int* q = new int(1);       // 忘掉 delete q; —— 泄漏

    // 3) 双重释放
    int* r = new int(2);
    delete r;
    // delete r;              // BUG: double free

    // 4) 防御式写法
    int* s = new int(3);
    delete s;
    s = nullptr;               // 置空后再次 delete 安全
    delete s;                  // 合法空操作
}

#include <iostream>

int main() {
    int n = 0;
    std::cin >> n;                 // 运行期才知道数量

    int* arr = new int[n];         // 动态数组
    for (int i = 0; i < n; ++i)
        arr[i] = i * i;

    // 传递时把大小一起带走
    auto sum = [=](int* a, int cnt) {
        int s = 0;
        for (int i = 0; i < cnt; ++i) s += a[i];
        return s;
    };
    std::cout << sum(arr, n) << "\n";

    delete[] arr;                  // 必须 delete[]
}

