int g_global = 1;            // 全局/静态区
const char* k_lit = "hi";    // 指向常量区

int main() {
    int   stack_val = 2;     // 栈
    int*  heap = new int(3); // 堆

    static int s_local = 4;  // 静态区（局部 static）

