#include <iostream>
#include <memory>

int main() {
    auto p1 = std::make_unique<int>(10);
    std::cout << *p1 << "\n";    // 10

    // 拷贝禁止
    // auto p2 = p1;             // 编译错误

    // 移动所有权
    std::unique_ptr<int> p2 = std::move(p1);
    std::cout << (p1 == nullptr) << "\n";   // 1（已转移）
    std::cout << *p2 << "\n";               // 10

    p2.reset(new int(20));     // 释放旧的，接管新的
    std::cout << *p2 << "\n";               // 20
    p2 = nullptr;              // 释放
}

