#include <iostream>
#include <memory>

struct B;                   // 前置声明

struct A {
    std::shared_ptr<B> b_ptr;
    ~A() { std::cout << "A 析构\n"; }
};
struct B {
    std::weak_ptr<A> a_ptr;   // 用 weak 打破循环
    ~B() { std::cout << "B 析构\n"; }
};

int main() {
    auto a = std::make_shared<A>();
    auto b = std::make_shared<B>();
    a->b_ptr = b;    // b 持 a 为 shared
    b->a_ptr = a;    // a 持 b 为 weak，不增加计数

    std::cout << "a count=" << a.use_count() << "\n";  // 1
    std::cout << "b count=" << b.use_count() << "\n";  // 2 (a+b_ptr)
}
// 若 a_ptr 也是 shared，两边计数永远 >=1 → 泄漏
// 用 weak 后，a 先析构，b 的 a_ptr.lock() 返回空

struct Node {
    int   val;
    Node* next;
};
Node* head = nullptr;

void push_front(int v) {
    Node* n = new Node{v, head};   // new: 指针连接
    head = n;
}

void pop_front() {
    if (!head) return;
    Node* old = head;              // 先保存
    head = head->next;             // 先改连接
    delete old;                    // 再释放
}

void print() {
    for (Node* n = head; n; n = n->next)  // 空指针 = 链尾
        std::cout << n->val << ' ';
    std::cout << "\n";
}

int main() {
    push_front(3); push_front(2); push_front(1);
    print();      // 1 2 3
    pop_front();
    print();      // 2 3
}

struct Shape {
    virtual double area() const = 0;      // 纯虚
    virtual ~Shape() = default;           // 必须 virtual 析构
};
struct Circle : Shape {
    double r;
    Circle(double x) : r(x) {}
    double area() const override { return 3.14 * r * r; }
};
struct Square : Shape {
    double s;
    Square(double x) : s(x) {}
    double area() const override { return s * s; }
};

int main() {
    std::vector<std::unique_ptr<Shape>> v;
    v.push_back(std::make_unique<Circle>(1.0));
    v.push_back(std::make_unique<Square>(2.0));

    for (const auto& sp : v)              // 基类指针
        std::cout << sp->area() << "\n"; // 各自动态分发
    // 3.14
    // 4
}
